1	#!/usr/bin/env node
2	// Prov Guard —— 软件供应链证明与完整性校验工具（零依赖，Node >= 18）。
3	//
4	// 子命令：
5	//   keygen   --key-dir <dir> [--name <prefix>]
6	//   generate --artifact <path> --key <private-key> --out <dir>
7	//   verify   --artifact <path> --proof <file> --signature <file> --key <public-key>
8	//
9	// 所有输出均为 UTF-8；成功结果写 stdout，错误结果写 stderr。
10	
11	import {
12	  createHash,
13	  createPrivateKey,
14	  createPublicKey,
15	  generateKeyPairSync,
16	  sign as cryptoSign,
17	  verify as cryptoVerify,
18	} from 'node:crypto';
19	import { constants as fsConstants, readFileSync, realpathSync } from 'node:fs';
20	import { access, mkdir, readdir, readFile, realpath, rename, rm, stat, writeFile } from 'node:fs/promises';
21	import { basename, dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';
22	import { fileURLToPath } from 'node:url';
23	
24	export const PROOF_VERSION = '1.0';
25	
26	// ---------------------------------------------------------------------------
27	// 错误类型：携带机器可读错误码，CLI 边界统一转换为非零退出。
28	// ---------------------------------------------------------------------------
29	
30	export const ERROR_CODES = Object.freeze({
31	  INPUT_NOT_FOUND: 'INPUT_NOT_FOUND',
32	  PERMISSION_DENIED: 'PERMISSION_DENIED',
33	  PROOF_INVALID: 'PROOF_INVALID',
34	  SIGNATURE_INVALID: 'SIGNATURE_INVALID',
35	  KEY_NOT_FOUND: 'KEY_NOT_FOUND',
36	  INTEGRITY_MISMATCH: 'INTEGRITY_MISMATCH',
37	  USAGE_ERROR: 'USAGE_ERROR',
38	});
39	
40	class ProvError extends Error {
41	  constructor(code, message, details) {
42	    super(message);
43	    this.name = 'ProvError';
44	    this.code = code;
45	    if (details !== undefined) this.details = details;
46	  }
47	}
48	
49	// 把 Node 底层错误归类为 INPUT_NOT_FOUND / PERMISSION_DENIED，其余原样抛出。
50	function wrapFsError(err, context) {
51	  if (err instanceof ProvError) return err;
52	  const where = context ? `${context}: ` : '';
53	  if (err && err.code === 'ENOENT') {
54	    return new ProvError(ERROR_CODES.INPUT_NOT_FOUND, `${where}路径不存在 (${err.path || 'unknown path'})`);
55	  }
56	  if (err && (err.code === 'EACCES' || err.code === 'EPERM')) {
57	    return new ProvError(ERROR_CODES.PERMISSION_DENIED, `${where}权限不足 (${err.path || 'unknown path'})`);
58	  }
59	  return err;
60	}
61	
62	// ---------------------------------------------------------------------------
63	// 路径与摘要工具
64	// ---------------------------------------------------------------------------
65	
66	// 清单中的相对路径统一使用正斜杠，保证跨平台稳定。
67	export function toPosix(relPath) {
68	  return relPath.split(sep).join('/');
69	}
70	
71	// 稳定哈希：SHA-256，摘要对象按 key 排序后以 UTF-8 序列化（两空格缩进）。
72	export function stableJsonStringify(value) {
73	  return JSON.stringify(sortDeep(value), null, 2);
74	}
75	
76	function sortDeep(value) {
77	  if (Array.isArray(value)) return value.map(sortDeep);
78	  if (value !== null && typeof value === 'object') {
79	    const out = {};
80	    for (const key of Object.keys(value).sort()) out[key] = sortDeep(value[key]);
81	    return out;
82	  }
83	  return value;
84	}
85	
86	export function sha256Hex(data) {
87	  return createHash('sha256').update(data).digest('hex');
88	}
89	
90	// 公钥指纹：对 SPKI 编码的 DER 字节取 SHA-256。写入证明并随证明一起签名，
91	// 验证时据此区分“使用了错误公钥”（指纹不一致）与“签名内容被篡改”（指纹一致但验签失败）。
92	export function keyFingerprint(keyObj) {
93	  return sha256Hex(keyObj.export({ type: 'spki', format: 'der' }));
94	}
95	
96	// ---------------------------------------------------------------------------
97	// 产物扫描：递归列出全部常规文件（含符号链接解引用后的目标），
98	// 空目录自然产生空清单；零字节文件按真实文件记录。
99	// ---------------------------------------------------------------------------
100	
101	async function walkFiles(rootDir) {
102	  const found = [];
103	  async function walk(dir) {
104	    let entries;
105	    try {
106	      entries = await readdir(dir, { withFileTypes: true });
107	    } catch (err) {
108	      throw wrapFsError(err, '读取产物目录');
109	    }
110	    for (const entry of entries) {
111	      const full = join(dir, entry.name);
112	      if (entry.isDirectory()) {
113	        await walk(full);
114	      } else if (entry.isFile()) {
115	        found.push(full);
116	      } else if (entry.isSymbolicLink()) {
117	        // 解引用后按目标类型处理：指向目录则继续递归，指向文件则记录。
118	        let target;
119	        try {
120	          target = await stat(full);
121	        } catch (err) {
122	          throw wrapFsError(err, '读取符号链接');
123	        }
124	        if (target.isDirectory()) await walk(full);
125	        else if (target.isFile()) found.push(full);
126	      }
127	      // 其他特殊文件（套接字/设备等）忽略。
128	    }
129	  }
130	  await walk(rootDir);
131	  return found;
132	}
133	
134	// 判断 root 是否位于 outDir 之内（用于从扫描结果排除输出目录自身）。
135	function isWithin(pathAbs, dirAbs) {
136	  const relPath = relative(dirAbs, pathAbs);
137	  return relPath === '' || (!!relPath && !relPath.startsWith('..') && !isAbsolute(relPath));
138	}
139	
140	async function fileTypeFromPath(fullPath, data) {
141	  // 极简魔数嗅探，仅用于清单的 type 字段；不识别时回退为扩展名或 "data"。
142	  // 一律使用字节数组，避免多字节字符串经 UTF-8 编码后长度/取值不符。
143	  const startsWith = (bytes) =>
144	    data.length >= bytes.length && bytes.every((b, i) => data[i] === b);
145	  if (startsWith([0x1f, 0x8b])) return 'application/gzip';
146	  if (startsWith([0x50, 0x4b, 0x03, 0x04])) return 'application/zip';
147	  if (startsWith([0x25, 0x50, 0x44, 0x46, 0x2d])) return 'application/pdf'; // %PDF-
148	  if (startsWith([0x7f, 0x45, 0x4c, 0x46])) return 'application/x-elf';
149	  if (startsWith([0x4d, 0x5a])) return 'application/x-dosexec'; // MZ
150	  if (startsWith([0xff, 0xd8, 0xff])) return 'image/jpeg';
151	  if (startsWith([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) return 'image/png';
152	  // 类脚本/文本：UTF BOM，或前 512 字节不含 NUL 则视为 text。
153	  if (
154	    startsWith([0xef, 0xbb, 0xbf]) ||
155	    startsWith([0xff, 0xfe]) ||
156	    startsWith([0xfe, 0xff])
157	  ) {
158	    return 'text/plain';
159	  }
160	  if (!data.subarray(0, 512).includes(0)) return 'text/plain';
161	  const ext = basename(fullPath).split('.').pop();
162	  return ext && ext !== basename(fullPath) ? `application/x-${ext.toLowerCase()}` : 'application/octet-stream';
163	}
164	
165	// 构建 SBOM。时间字段不进入清单，文件摘要只依赖文件字节与相对路径。
166	// excludeDir 为输出目录的绝对路径（若位于产物内部则排除）。
167	export async function buildSbom(artifactPath, excludeDir) {
168	  const artifactAbs = resolve(artifactPath);
169	  let artifactStat;
170	  try {
171	    artifactStat = await stat(artifactAbs);
172	  } catch (err) {
173	    throw wrapFsError(err, '读取产物');
174	  }
175	
176	  const rootDir = artifactStat.isDirectory() ? artifactAbs : dirname(artifactAbs);
177	  const excludeAbs = excludeDir ? resolve(excludeDir) : null;
178	
179	  let files;
180	  if (artifactStat.isDirectory()) {
181	    files = await walkFiles(artifactAbs);
182	  } else {
183	    files = [artifactAbs];
184	  }
185	
186	  const entries = [];
187	  for (const full of files) {
188	    if (excludeAbs && isWithin(full, excludeAbs)) continue;
189	    let data;
190	    try {
191	      data = await readFile(full);
192	    } catch (err) {
193	      throw wrapFsError(err, '读取产物文件');
194	    }
195	    const relPath = toPosix(relative(rootDir, full));
196	    entries.push({
197	      path: relPath,
198	      sha256: sha256Hex(data),
199	      size: data.length,
200	      type: await fileTypeFromPath(full, data),
201	    });
202	  }
203	
204	  // 按相对路径排序，保证同一输入产生字节级一致的清单。
205	  entries.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
206	
207	  return {
208	    schemaVersion: '1.0',
209	    artifactName: artifactStat.isDirectory() ? basename(artifactAbs) : basename(artifactAbs),
210	    rootType: artifactStat.isDirectory() ? 'directory' : 'file',
211	    files: entries,
212	  };
213	}
214	
215	// 顶层产物摘要：对“排序后的文件条目列表”做稳定哈希。
216	// 任何字节变化、文件新增/删除/重命名都会改变该摘要。
217	export function computeArtifactDigest(sbom) {
218	  return sha256Hex(stableJsonStringify(sbom.files));
219	}
220	
221	// ---------------------------------------------------------------------------
222	// 密钥与签名（Ed25519，PEM）
223	// ---------------------------------------------------------------------------
224	
225	function readPrivateKey(keyPath) {
226	  let pem;
227	  try {
228	    pem = readFileSync(keyPath);
229	  } catch (err) {
230	    throw wrapFsError(err, '读取私钥');
231	  }
232	  let keyObj;
233	  try {
234	    keyObj = createPrivateKey({ key: pem, format: 'pem' });
235	  } catch {
236	    throw new ProvError(ERROR_CODES.KEY_NOT_FOUND, `私钥无法解析或格式不受支持: ${keyPath}`);
237	  }
238	  if (keyObj.asymmetricKeyType !== 'ed25519') {
239	    throw new ProvError(
240	      ERROR_CODES.KEY_NOT_FOUND,
241	      `私钥类型不是 Ed25519（实际为 ${keyObj.asymmetricKeyType}）: ${keyPath}`,
242	    );
243	  }
244	  return keyObj;
245	}
246	
247	function readPublicKey(keyPath) {
248	  let pem;
249	  try {
250	    pem = readFileSync(keyPath);
251	  } catch (err) {
252	    throw wrapFsError(err, '读取公钥');
253	  }
254	  let keyObj;
255	  try {
256	    keyObj = createPublicKey({ key: pem, format: 'pem' });
257	  } catch {
258	    throw new ProvError(ERROR_CODES.KEY_NOT_FOUND, `公钥无法解析或格式不受支持: ${keyPath}`);
259	  }
260	  if (keyObj.asymmetricKeyType !== 'ed25519') {
261	    throw new ProvError(
262	      ERROR_CODES.KEY_NOT_FOUND,
263	      `公钥类型不是 Ed25519（实际为 ${keyObj.asymmetricKeyType}）: ${keyPath}`,
264	    );
265	  }
266	  return keyObj;
267	}
268	
269	// 生成阶段时间戳采用 UTC ISO-8601；它只写入 proof，不参与任何摘要。
270	function nowIso() {
271	  return new Date().toISOString();
272	}
273	
274	// ---------------------------------------------------------------------------
275	// keygen
276	// ---------------------------------------------------------------------------
277	
278	export async function keygen({ keyDir, name = 'provguard' }) {
279	  const absDir = resolve(keyDir);
280	  try {
281	    await mkdir(absDir, { recursive: true });
282	  } catch (err) {
283	    throw wrapFsError(err, '创建密钥目录');
284	  }
285	  const { publicKey, privateKey } = generateKeyPairSync('ed25519');
286	  const privPath = join(absDir, `${name}.private.pem`);
287	  const pubPath = join(absDir, `${name}.public.pem`);
288	  try {
289	    await writeFile(
290	      privPath,
291	      privateKey.export({ type: 'pkcs8', format: 'pem' }),
292	      { mode: 0o600 },
293	    );
294	    await writeFile(
295	      pubPath,
296	      publicKey.export({ type: 'spki', format: 'pem' }),
297	      { mode: 0o644 },
298	    );
299	  } catch (err) {
300	    throw wrapFsError(err, '写入密钥');
301	  }
302	  return { privateKeyPath: privPath, publicKeyPath: pubPath };
303	}
304	
305	// ---------------------------------------------------------------------------
306	// generate
307	// ---------------------------------------------------------------------------
308	
309	export async function generate({ artifact, key, out }) {
310	  // 输入检查：产物与私钥必须存在且可读。
311	  const artifactAbs = resolve(artifact);
312	  const keyAbs = resolve(key);
313	  for (const [p, label] of [
314	    [artifactAbs, '产物'],
315	    [keyAbs, '私钥'],
316	  ]) {
317	    try {
318	      await access(p, fsConstants.R_OK);
319	    } catch (err) {
320	      throw wrapFsError(err, `读取${label}`);
321	    }
322	  }
323	
324	  const outAbs = resolve(out);
325	  const parent = dirname(outAbs);
326	  try {
327	    await mkdir(parent, { recursive: true });
328	  } catch (err) {
329	    throw wrapFsError(err, '创建输出目录');
330	  }
331	
332	  // 若输出目录尚不存在，先按真实路径创建，再据此排除。
333	  try {
334	    await mkdir(outAbs, { recursive: true });
335	  } catch (err) {
336	    throw wrapFsError(err, '创建输出目录');
337	  }
338	  let outReal;
339	  try {
340	    outReal = await realpath(outAbs);
341	  } catch (err) {
342	    throw wrapFsError(err, '解析输出目录');
343	  }
344	
345	  const privateKey = readPrivateKey(keyAbs);
346	  // 由私钥导出对应公钥，记录其指纹到证明中，供验证区分错误公钥与签名失配。
347	  const signingPublicKey = createPublicKey(privateKey);
348	  const signerKeyFingerprint = keyFingerprint(signingPublicKey);
349	
350	  const sbom = await buildSbom(artifactAbs, outReal);
351	  const artifactDigest = computeArtifactDigest(sbom);
352	
353	  const proof = {
354	    proofVersion: PROOF_VERSION,
355	    artifactName: basename(artifactAbs),
356	    artifactDigest,
357	    fileName: basename(artifactAbs),
358	    size: sbom.files.reduce((n, f) => n + f.size, 0),
359	    generatedAt: nowIso(),
360	    signerKeyFingerprint,
361	    files: sbom.files,
362	  };
363	  // 稳定字段顺序：proof 先按既定顺序构造，再整体排序输出。
364	  const proofJson = stableJsonStringify(proof) + '\n';
365	  const sbomJson = stableJsonStringify(sbom) + '\n';
366	
367	  // 对证明的规范字节（不含尾部换行）签名，验证时使用同一规范形式。
368	  // Ed25519 为纯签名算法，不接受摘要算法参数，故用 sign(null, data, key)。
369	  const signature = cryptoSign(null, Buffer.from(proofJson.trimEnd(), 'utf8'), privateKey);
370	  const signatureB64 = signature.toString('base64') + '\n';
371	
372	  const proofPath = join(outReal, 'proof.json');
373	  const sbomPath = join(outReal, 'sbom.json');
374	  const sigPath = join(outReal, 'proof.json.sig');
375	  try {
376	    await atomicWrite(proofPath, proofJson);
377	    await atomicWrite(sbomPath, sbomJson);
378	    await atomicWrite(sigPath, signatureB64);
379	  } catch (err) {
380	    throw wrapFsError(err, '写入证明产物');
381	  }
382	
383	  return {
384	    proofPath,
385	    sbomPath,
386	    signaturePath: sigPath,
387	    artifactDigest,
388	    fileCount: sbom.files.length,
389	    proofVersion: PROOF_VERSION,
390	  };
391	}
392	
393	// 同目录临时文件 + rename，避免半成品证明文件留在输出目录。
394	async function atomicWrite(target, contents) {
395	  const dir = dirname(target);
396	  const tmp = join(dir, `.${basename(target)}.${process.pid}.tmp`);
397	  await writeFile(tmp, contents, { mode: 0o644 });
398	  try {
399	    await rename(tmp, target);
400	  } catch (err) {
401	    await rm(tmp, { force: true });
402	    throw err;
403	  }
404	}
405	
406	// ---------------------------------------------------------------------------
407	// verify
408	// ---------------------------------------------------------------------------
409	
410	export async function verify({ artifact, proof: proofPath, signature: sigPath, key: pubKeyPath }) {
411	  const artifactAbs = resolve(artifact);
412	  const proofAbs = resolve(proofPath);
413	  const sigAbs = resolve(sigPath);
414	  const keyAbs = resolve(pubKeyPath);
415	
416	  // 1) 所有输入必须存在且可读。
417	  for (const [p, label] of [
418	    [artifactAbs, '产物'],
419	    [proofAbs, '证明文件'],
420	    [sigAbs, '签名文件'],
421	    [keyAbs, '公钥'],
422	  ]) {
423	    try {
424	      await access(p, fsConstants.R_OK);
425	    } catch (err) {
426	      throw wrapFsError(err, `读取${label}`);
427	    }
428	  }
429	
430	  // 2) 公钥必须可解析且为 Ed25519 —— 错误/不支持的公钥归 KEY_NOT_FOUND。
431	  const publicKey = readPublicKey(keyAbs);
432	
433	  // 3) 证明文件必须是可解析的 JSON 且结构合法 —— 否则 PROOF_INVALID。
434	  let proofText;
435	  try {
436	    proofText = await readFileUtf8(proofAbs);
437	  } catch (err) {
438	    throw wrapFsError(err, '读取证明文件');
439	  }
440	  let proof;
441	  try {
442	    proof = JSON.parse(proofText);
443	  } catch {
444	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明文件不是合法的 JSON');
445	  }
446	  const proofError = validateProof(proof);
447	  if (proofError) {
448	    throw new ProvError(ERROR_CODES.PROOF_INVALID, proofError);
449	  }
450	
451	  // 4) 签名文件必须是合法 Base64 且长度符合 Ed25519（64 字节）—— 否则 PROOF_INVALID。
452	  const sigText = await readFileUtf8(sigAbs);
453	  const sigB64 = sigText.replace(/\s+/g, '');
454	  let sigBuf;
455	  if (!/^[A-Za-z0-9+/]*={0,2}$/.test(sigB64) || sigB64.length === 0) {
456	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '签名文件不是合法的 Base64 内容');
457	  }
458	  try {
459	    sigBuf = Buffer.from(sigB64, 'base64');
460	  } catch {
461	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '签名文件无法解码为字节');
462	  }
463	  if (sigBuf.length !== 64) {
464	    throw new ProvError(
465	      ERROR_CODES.PROOF_INVALID,
466	      `签名长度非法（Ed25519 应为 64 字节，实际 ${sigBuf.length} 字节）`,
467	    );
468	  }
469	
470	  // 5) 重算证明的规范字节并验签。
471	  //    以磁盘上的 proof.json 原样为真，重新序列化其解析结果用于验签；
472	  //    generate 写出的即为稳定规范形式，因此往返一致。
473	  //
474	  //    错误归类（三者互不相同）：
475	  //      - 提供的公钥与证明中记录的签钥指纹不一致  -> KEY_NOT_FOUND（错误公钥）
476	  //      - 公钥一致但签名验证失败                  -> SIGNATURE_INVALID（签名内容不匹配）
477	  //      - 签名文件本身格式非法（前面）            -> PROOF_INVALID
478	  const providedFingerprint = keyFingerprint(publicKey);
479	  if (providedFingerprint.toLowerCase() !== proof.signerKeyFingerprint.toLowerCase()) {
480	    throw new ProvError(
481	      ERROR_CODES.KEY_NOT_FOUND,
482	      '提供的公钥与证明记录的签名密钥不一致（可能使用了错误公钥）',
483	      {
484	        providedKeyFingerprint: providedFingerprint,
485	        proofKeyFingerprint: proof.signerKeyFingerprint,
486	      },
487	    );
488	  }
489	
490	  const canonicalProof = stableJsonStringify(proof);
491	  let sigOk = false;
492	  try {
493	    sigOk = cryptoVerify(null, Buffer.from(canonicalProof, 'utf8'), publicKey, sigBuf);
494	  } catch {
495	    sigOk = false;
496	  }
497	  if (!sigOk) {
498	    throw new ProvError(
499	      ERROR_CODES.SIGNATURE_INVALID,
500	      '签名与证明内容不匹配（证明可能被改动，或签名已损坏）',
501	    );
502	  }
503	
504	  // 6) 签名通过后重新扫描产物并逐项比对 —— 任何差异均为 INTEGRITY_MISMATCH。
505	  //    排除输出目录：证明/签名/清单通常与产物相邻，验证时不得把它们计入产物。
506	  const excludeDir = inferExcludeDir(proofAbs, artifactAbs);
507	  const currentSbom = await buildSbom(artifactAbs, excludeDir);
508	  const currentDigest = computeArtifactDigest(currentSbom);
509	
510	  const mismatches = diffManifest(proof, currentSbom, currentDigest);
511	  if (mismatches.length > 0) {
512	    throw new ProvError(
513	      ERROR_CODES.INTEGRITY_MISMATCH,
514	      `检测到 ${mismatches.length} 处完整性差异`,
515	      { mismatches },
516	    );
517	  }
518	
519	  return {
520	    status: 'VERIFIED',
521	    proofVersion: proof.proofVersion,
522	    artifactDigest: currentDigest,
523	    fileCount: currentSbom.files.length,
524	  };
525	}
526	
527	function inferExcludeDir(proofAbs, artifactAbs) {
528	  // 证明文件所在目录若位于产物之内，则将其视为生成时的输出目录予以排除。
529	  const proofDir = dirname(proofAbs);
530	  if (isWithin(proofDir, artifactAbs)) return proofDir;
531	  return null;
532	}
533	
534	async function readFileUtf8(p) {
535	  try {
536	    return (await readFile(p, 'utf8'));
537	  } catch (err) {
538	    throw wrapFsError(err, '读取文件');
539	  }
540	}
541	
542	function validateProof(proof) {
543	  if (proof === null || typeof proof !== 'object' || Array.isArray(proof)) {
544	    return '证明文件顶层必须是 JSON 对象';
545	  }
546	  const needString = ['proofVersion', 'artifactName', 'artifactDigest', 'fileName', 'generatedAt', 'signerKeyFingerprint'];
547	  for (const k of needString) {
548	    if (typeof proof[k] !== 'string' || proof[k].length === 0) {
549	      return `证明字段缺失或类型非法: ${k}`;
550	    }
551	  }
552	  if (!/^[0-9a-f]{64}$/i.test(proof.artifactDigest)) {
553	    return '证明中的 artifactDigest 不是合法的 SHA-256 十六进制摘要';
554	  }
555	  if (!/^[0-9a-f]{64}$/i.test(proof.signerKeyFingerprint)) {
556	    return '证明中的 signerKeyFingerprint 不是合法的 SHA-256 十六进制摘要';
557	  }
558	  if (typeof proof.size !== 'number' || !Number.isFinite(proof.size) || proof.size < 0) {
559	    return '证明字段缺失或类型非法: size';
560	  }
561	  if (!Array.isArray(proof.files)) return '证明字段缺失或类型非法: files';
562	  const seen = new Set();
563	  for (const f of proof.files) {
564	    if (f === null || typeof f !== 'object') return '清单条目必须是对象';
565	    if (typeof f.path !== 'string' || f.path.length === 0) return '清单条目 path 非法';
566	    if (f.path.includes('\\')) return `清单相对路径必须使用正斜杠: ${f.path}`;
567	    if (f.path.startsWith('/') || f.path.split('/').includes('..')) {
568	      return `清单相对路径越界: ${f.path}`;
569	    }
570	    if (seen.has(f.path)) return `清单路径重复: ${f.path}`;
571	    seen.add(f.path);
572	    if (!/^[0-9a-f]{64}$/i.test(f.sha256)) return `清单条目摘要非法: ${f.path}`;
573	    if (typeof f.size !== 'number' || !Number.isFinite(f.size) || f.size < 0) {
574	      return `清单条目大小非法: ${f.path}`;
575	    }
576	    if (typeof f.type !== 'string' || f.type.length === 0) return `清单条目类型非法: ${f.path}`;
577	  }
578	  return null;
579	}
580	
581	// 返回差异列表；每条 {path, kind}。顶层摘要差异兜底。
582	function diffManifest(proof, currentSbom, currentDigest) {
583	  const mismatches = [];
584	  const proofFiles = new Map(proof.files.map((f) => [f.path, f]));
585	  const currentFiles = new Map(currentSbom.files.map((f) => [f.path, f]));
586	
587	  for (const [path, pf] of proofFiles) {
588	    const cur = currentFiles.get(path);
589	    if (!cur) {
590	      mismatches.push({ path, kind: 'missing' }); // 证明中存在、产物中已删除
591	      continue;
592	    }
593	    if (cur.sha256.toLowerCase() !== pf.sha256.toLowerCase()) {
594	      mismatches.push({ path, kind: 'content-modified' });
595	    } else if (cur.size !== pf.size) {
596	      mismatches.push({ path, kind: 'size-mismatch' });
597	    }
598	  }
599	  for (const path of currentFiles.keys()) {
600	    if (!proofFiles.has(path)) {
601	      mismatches.push({ path, kind: 'added' }); // 产物中新出现的文件
602	    }
603	  }
604	
605	  if (proof.artifactDigest.toLowerCase() !== currentDigest.toLowerCase() && mismatches.length === 0) {
606	    // 理论上不会发生（逐文件比对已覆盖），作为顶层摘要兜底。
607	    mismatches.push({ path: '.', kind: 'artifact-digest-mismatch' });
608	  }
609	  if (proof.fileName !== currentSbom.artifactName) {
610	    mismatches.push({ path: '.', kind: 'artifact-name-mismatch' });
611	  }
612	
613	  mismatches.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : a.kind < b.kind ? -1 : 1));
614	  return mismatches;
615	}
616	
617	// ---------------------------------------------------------------------------
618	// CLI
619	// ---------------------------------------------------------------------------
620	
621	function parseArgs(argv) {
622	  const args = { _: [] };
623	  for (let i = 0; i < argv.length; i += 1) {
624	    const a = argv[i];
625	    if (a.startsWith('--')) {
626	      const key = a.slice(2);
627	      const next = argv[i + 1];
628	      if (next === undefined || next.startsWith('--')) {
629	        args[key] = true;
630	      } else {
631	        args[key] = next;
632	        i += 1;
633	      }
634	    } else {
635	      args._.push(a);
636	    }
637	  }
638	  return args;
639	}
640	
641	function usage() {
642	  return [
643	    'Prov Guard —— 软件供应链证明与完整性校验工具',
644	    '',
645	    '用法:',
646	    '  provguard keygen   --key-dir <dir> [--name <prefix>]',
647	    '  provguard generate --artifact <path> --key <private.pem> --out <dir>',
648	    '  provguard verify   --artifact <path> --proof <proof.json> \\',
649	    '                      --signature <proof.json.sig> --key <public.pem>',
650	    '',
651	    'generate 输出: proof.json / proof.json.sig / sbom.json',
652	    '成功状态: VERIFIED；错误码见 README。',
653	  ].join('\n');
654	}
655	
656	function printMachineError(err) {
657	  const payload = {
658	    status: 'ERROR',
659	    errorCode: err instanceof ProvError ? err.code : 'INTERNAL_ERROR',
660	    message: err && err.message ? err.message : String(err),
661	  };
662	  if (err && err.details !== undefined) payload.details = err.details;
663	  return stableJsonStringify(payload);
664	}
665	
666	async function main(argv) {
667	  const args = parseArgs(argv);
668	  const command = args._[0];
669	
670	  try {
671	    if (!command || command === 'help' || command === '--help' || command === '-h') {
672	      process.stdout.write(`${usage()}\n`);
673	      return 0;
674	    }
675	
676	    if (command === 'keygen') {
677	      if (!args['key-dir']) {
678	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '缺少必填参数 --key-dir');
679	      }
680	      const r = await keygen({ keyDir: args['key-dir'], name: args.name || 'provguard' });
681	      process.stdout.write(
682	        `${stableJsonStringify({ status: 'KEYGEN_OK', ...r })}\n`,
683	      );
684	      return 0;
685	    }
686	
687	    if (command === 'generate') {
688	      const missing = ['artifact', 'key', 'out'].filter((k) => typeof args[k] !== 'string');
689	      if (missing.length) {
690	        throw new ProvError(
691	          ERROR_CODES.USAGE_ERROR,
692	          `缺少必填参数: ${missing.map((m) => `--${m}`).join(', ')}`,
693	        );
694	      }
695	      const r = await generate({ artifact: args.artifact, key: args.key, out: args.out });
696	      process.stdout.write(
697	        `${stableJsonStringify({
698	          status: 'GENERATED',
699	          proofVersion: r.proofVersion,
700	          artifactDigest: r.artifactDigest,
701	          fileCount: r.fileCount,
702	          proofPath: r.proofPath,
703	          sbomPath: r.sbomPath,
704	          signaturePath: r.signaturePath,
705	        })}\n`,
706	      );
707	      return 0;
708	    }
709	
710	    if (command === 'verify') {
711	      const missing = ['artifact', 'proof', 'signature', 'key'].filter((k) => typeof args[k] !== 'string');
712	      if (missing.length) {
713	        throw new ProvError(
714	          ERROR_CODES.USAGE_ERROR,
715	          `缺少必填参数: ${missing.map((m) => `--${m}`).join(', ')}`,
716	        );
717	      }
718	      const r = await verify({
719	        artifact: args.artifact,
720	        proof: args.proof,
721	        signature: args.signature,
722	        key: args.key,
723	      });
724	      process.stdout.write(`${stableJsonStringify(r)}\n`);
725	      return 0;
726	    }
727	
728	    throw new ProvError(ERROR_CODES.USAGE_ERROR, `未知子命令: ${command}`);
729	  } catch (err) {
730	    // stderr 仅输出机器可读 JSON；用法帮助走 stdout，避免污染错误流。
731	    process.stderr.write(`${printMachineError(err)}\n`);
732	    if (err instanceof ProvError && err.code === ERROR_CODES.USAGE_ERROR) {
733	      process.stdout.write(`\n${usage()}\n`);
734	    }
735	    return 1;
736	  }
737	}
738	
739	// 仅作为脚本直接运行时执行 main；被测试 import 时不执行。
740	if (process.argv[1] && realpathSync(process.argv[1]) === fileURLToPath(import.meta.url)) {
741	  main(process.argv.slice(2)).then((code) => {
742	    process.exitCode = code;
743	  });
744	}
745	
746	export { main, ProvError, ERROR_CODES as CODES };
747

